/* Recreate the Phase 2 operational tenant guards with the SET options required
   for DML against indexed computed columns and indexed views. Guard behavior is
   intentionally identical to V11-OperationalTenantWriteGuards.sql. */
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER TRIGGER purchase.TR_Suppliers_TenantGuard ON purchase.Suppliers AFTER INSERT, UPDATE AS
BEGIN
 SET NOCOUNT ON; DECLARE @t uniqueidentifier=TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N'TenantId'));
 IF @t IS NULL THROW 51400,'Tenant context is required for supplier writes.',1;
 UPDATE s SET TenantId=@t FROM purchase.Suppliers s JOIN inserted i ON i.SupplierId=s.SupplierId WHERE s.TenantId IS NULL;
 IF EXISTS(SELECT 1 FROM purchase.Suppliers s JOIN inserted i ON i.SupplierId=s.SupplierId WHERE s.TenantId<>@t) THROW 51401,'Supplier is outside the current tenant.',1;
END;
GO

/* The following Phase 2 procedures were also found with captured
   QUOTED_IDENTIFIER OFF during post-V24 flow verification. Their live,
   tenant-parameterized definitions are restated explicitly so the required
   module SET metadata is deterministic. */
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE inventory.PhysicalVerification_Post @WarehouseId uniqueidentifier,@VerificationDate datetimeoffset,@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('PHY-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@adjust uniqueidentifier=NULL,@tx uniqueidentifier=NEWID();DECLARE @i table(ProductId uniqueidentifier,ZoneId uniqueidentifier,BinId uniqueidentifier,BatchNo nvarchar(100),SerialNo nvarchar(100),CountedQuantity decimal(18,4),UnitCost decimal(18,4),SystemQuantity decimal(18,4));INSERT @i(ProductId,ZoneId,BinId,BatchNo,SerialNo,CountedQuantity,UnitCost)SELECT * FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',ZoneId uniqueidentifier '$.ZoneId',BinId uniqueidentifier '$.BinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',CountedQuantity decimal(18,4) '$.CountedQuantity',UnitCost decimal(18,4) '$.UnitCost');UPDATE i SET SystemQuantity=ISNULL((SELECT SUM(b.QuantityOnHand) FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'')),0) FROM @i i;INSERT inventory.PhysicalStockVerification(VerificationId,VerificationNo,VerificationDate,WarehouseId,ApprovalStatus,Remarks,ApprovedBy,ApprovedOn,CreatedBy)VALUES(@id,@no,@VerificationDate,@WarehouseId,@ApprovalStatus,@Remarks,CASE WHEN @ApprovalStatus='APPROVED' THEN @CreatedBy END,CASE WHEN @ApprovalStatus='APPROVED' THEN SYSUTCDATETIME() END,@CreatedBy);INSERT inventory.PhysicalStockVerificationItems(VerificationId,ProductId,ZoneId,BinId,BatchNo,SerialNo,SystemQuantity,CountedQuantity,UnitCost)SELECT @id,ProductId,ZoneId,BinId,BatchNo,SerialNo,SystemQuantity,CountedQuantity,UnitCost FROM @i;
IF @ApprovalStatus='APPROVED' AND EXISTS(SELECT 1 FROM @i WHERE CountedQuantity<>SystemQuantity) BEGIN DECLARE @json nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,ABS(CountedQuantity-SystemQuantity) Quantity,UnitCost FROM @i WHERE CountedQuantity<>SystemQuantity FOR JSON PATH);DECLARE @result table(OperationId uniqueidentifier,TransactionId uniqueidentifier,Number nvarchar(50));IF NOT EXISTS(SELECT 1 FROM @i WHERE CountedQuantity<SystemQuantity) OR NOT EXISTS(SELECT 1 FROM @i WHERE CountedQuantity>SystemQuantity) BEGIN DECLARE @type nvarchar(10)=CASE WHEN EXISTS(SELECT 1 FROM @i WHERE CountedQuantity>SystemQuantity) THEN 'INCREASE' ELSE 'DECREASE' END;INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,@type,'PHYSICAL_VERIFICATION','APPROVED',@Remarks,@json,@CreatedBy,@TenantId;SELECT TOP 1 @adjust=OperationId,@tx=TransactionId FROM @result;END ELSE BEGIN DECLARE @up nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,CountedQuantity-SystemQuantity Quantity,UnitCost FROM @i WHERE CountedQuantity>SystemQuantity FOR JSON PATH),@down nvarchar(max)=(SELECT ProductId,ZoneId SourceZoneId,BinId SourceBinId,BatchNo,SerialNo,SystemQuantity-CountedQuantity Quantity,UnitCost FROM @i WHERE CountedQuantity<SystemQuantity FOR JSON PATH);INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,'INCREASE','PHYSICAL_VERIFICATION','APPROVED',@Remarks,@up,@CreatedBy,@TenantId;INSERT @result EXEC inventory.StockAdjustment_Post @WarehouseId,'DECREASE','PHYSICAL_VERIFICATION','APPROVED',@Remarks,@down,@CreatedBy,@TenantId;SELECT TOP 1 @adjust=OperationId,@tx=TransactionId FROM @result;END UPDATE inventory.PhysicalStockVerification SET GeneratedAdjustmentId=@adjust WHERE VerificationId=@id;END COMMIT;SELECT @id OperationId,@tx TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE inventory.StockAdjustment_Post @WarehouseId uniqueidentifier,@AdjustmentType nvarchar(10),@ReasonCode nvarchar(50),@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY
DECLARE @id uniqueidentifier=NEWID(),@tx uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('ADJ-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff')),@sign decimal(18,4)=CASE WHEN @AdjustmentType='INCREASE' THEN 1 ELSE -1 END;
DECLARE @items table(ProductId uniqueidentifier,ZoneId uniqueidentifier NULL,BinId uniqueidentifier NULL,BatchNo nvarchar(100) NULL,SerialNo nvarchar(100) NULL,Quantity decimal(18,4),UnitCost decimal(18,4));INSERT @items SELECT ProductId,SourceZoneId,SourceBinId,BatchNo,SerialNo,Quantity,UnitCost FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',SourceZoneId uniqueidentifier '$.SourceZoneId',SourceBinId uniqueidentifier '$.SourceBinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',Quantity decimal(18,4) '$.Quantity',UnitCost decimal(18,4) '$.UnitCost');IF NOT EXISTS(SELECT 1 FROM @items) THROW 51000,'At least one adjustment item is required.',1;
INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy,CreatedOn)VALUES(@tx,@no,SYSUTCDATETIME(),CASE WHEN @AdjustmentType='INCREASE' THEN 'ADJUSTMENT_IN' ELSE 'ADJUSTMENT_OUT' END,'STOCK_ADJUSTMENT',@id,@WarehouseId,@Remarks,@CreatedBy,SYSUTCDATETIME());INSERT inventory.StockAdjustments(StockAdjustmentId,TransactionId,AdjustmentNo,AdjustmentType,ReasonCode,ApprovalStatus,ApprovedBy,ApprovedOn,CreatedOn)VALUES(@id,@tx,@no,@AdjustmentType,@ReasonCode,@ApprovalStatus,CASE WHEN @ApprovalStatus='APPROVED' THEN @CreatedBy END,CASE WHEN @ApprovalStatus='APPROVED' THEN SYSUTCDATETIME() END,SYSUTCDATETIME());INSERT inventory.StockAdjustmentItems(StockAdjustmentId,ProductId,ZoneId,BinId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @id,* FROM @items;
IF @ApprovalStatus='APPROVED' BEGIN IF @AdjustmentType='DECREASE' AND EXISTS(SELECT 1 FROM @items i OUTER APPLY(SELECT SUM(QuantityAvailable) q FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND (b.ZoneId=i.ZoneId OR b.ZoneId IS NULL AND i.ZoneId IS NULL) AND (b.BinId=i.BinId OR b.BinId IS NULL AND i.BinId IS NULL) AND (b.BatchNo=i.BatchNo OR b.BatchNo IS NULL AND i.BatchNo IS NULL) AND (b.SerialNo=i.SerialNo OR b.SerialNo IS NULL AND i.SerialNo IS NULL))b WHERE ISNULL(b.q,0)<i.Quantity) AND NOT EXISTS(SELECT 1 FROM inventory.InventorySettings WHERE NegativeStockAllowed=1) THROW 51001,'Insufficient available stock.',1;
INSERT inventory.InventoryBalances(ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,QuantityOnHand,QuantityReserved,AverageCost,LastPurchaseCost,LastUpdated,CreatedOn,CreatedBy)SELECT i.ProductId,@WarehouseId,i.ZoneId,i.BinId,i.BatchNo,i.SerialNo,0,0,i.UnitCost,i.UnitCost,SYSUTCDATETIME(),SYSUTCDATETIME(),@CreatedBy FROM @items i WHERE NOT EXISTS(SELECT 1 FROM inventory.InventoryBalances b WHERE b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''));UPDATE b SET QuantityOnHand=b.QuantityOnHand+@sign*i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @items i ON b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');
INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @tx,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @items;INSERT inventory.StockMovementHistory(TransactionId,TransactionDetailId,MovementDate,MovementType,ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,Quantity,BalanceAfter,ReferenceType,ReferenceId,Remarks,CreatedBy)SELECT @tx,d.TransactionDetailId,SYSUTCDATETIME(),CASE WHEN @sign=1 THEN 'ADJUSTMENT_IN' ELSE 'ADJUSTMENT_OUT' END,d.ProductId,@WarehouseId,i.ZoneId,i.BinId,d.BatchNo,d.SerialNo,@sign*d.Quantity,b.QuantityOnHand,'STOCK_ADJUSTMENT',@id,@Remarks,@CreatedBy FROM inventory.InventoryTransactionDetails d JOIN @items i ON i.ProductId=d.ProductId AND ISNULL(i.BatchNo,'')=ISNULL(d.BatchNo,'') AND ISNULL(i.SerialNo,'')=ISNULL(d.SerialNo,'') JOIN inventory.InventoryBalances b ON b.ProductId=i.ProductId AND b.WarehouseId=@WarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.ZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.BinId,'00000000-0000-0000-0000-000000000000') WHERE d.TransactionId=@tx;
IF OBJECT_ID('finance.PostStockAdjustment') IS NOT NULL EXEC finance.PostStockAdjustment @TransactionId=@tx,@CreatedBy=@CreatedBy;END
COMMIT;SELECT @id OperationId,@tx TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE inventory.StockTransfer_Post @SourceWarehouseId uniqueidentifier,@DestinationWarehouseId uniqueidentifier,@TransferDate datetimeoffset,@ApprovalStatus nvarchar(20),@Remarks nvarchar(1000)=NULL,@ItemsJson nvarchar(max),@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;BEGIN TRAN;BEGIN TRY DECLARE @id uniqueidentifier=NEWID(),@out uniqueidentifier=NEWID(),@in uniqueidentifier=NEWID(),@no nvarchar(50)=CONCAT('TRF-',FORMAT(SYSUTCDATETIME(),'yyyyMMddHHmmssfff'));DECLARE @i table(ProductId uniqueidentifier,SourceZoneId uniqueidentifier,SourceBinId uniqueidentifier,DestinationZoneId uniqueidentifier,DestinationBinId uniqueidentifier,BatchNo nvarchar(100),SerialNo nvarchar(100),Quantity decimal(18,4),UnitCost decimal(18,4));INSERT @i SELECT * FROM OPENJSON(@ItemsJson) WITH(ProductId uniqueidentifier '$.ProductId',SourceZoneId uniqueidentifier '$.SourceZoneId',SourceBinId uniqueidentifier '$.SourceBinId',DestinationZoneId uniqueidentifier '$.DestinationZoneId',DestinationBinId uniqueidentifier '$.DestinationBinId',BatchNo nvarchar(100) '$.BatchNo',SerialNo nvarchar(100) '$.SerialNo',Quantity decimal(18,4) '$.Quantity',UnitCost decimal(18,4) '$.UnitCost');IF NOT EXISTS(SELECT 1 FROM @i)THROW 51000,'At least one transfer item is required.',1;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@out,@no+'-OUT',@TransferDate,'TRANSFER_OUT','STOCK_TRANSFER',@id,@SourceWarehouseId,@Remarks,@CreatedBy),(@in,@no+'-IN',@TransferDate,'TRANSFER_IN','STOCK_TRANSFER',@id,@DestinationWarehouseId,@Remarks,@CreatedBy);INSERT inventory.StockTransfers(StockTransferId,TransferNo,SourceTransactionId,DestinationTransactionId,SourceWarehouseId,DestinationWarehouseId,ApprovalStatus,TransferDate,Remarks,CreatedBy,CreatedOn)VALUES(@id,@no,@out,@in,@SourceWarehouseId,@DestinationWarehouseId,CASE WHEN @ApprovalStatus='APPROVED' THEN 'COMPLETED' ELSE @ApprovalStatus END,@TransferDate,@Remarks,@CreatedBy,SYSUTCDATETIME());INSERT inventory.StockTransferItems(StockTransferId,ProductId,SourceZoneId,SourceBinId,DestinationZoneId,DestinationBinId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @id,* FROM @i;
IF @ApprovalStatus='APPROVED' BEGIN IF EXISTS(SELECT 1 FROM @i i OUTER APPLY(SELECT SUM(QuantityAvailable) q FROM inventory.InventoryBalances b WITH(UPDLOCK,HOLDLOCK) WHERE b.ProductId=i.ProductId AND b.WarehouseId=@SourceWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''))b WHERE ISNULL(b.q,0)<i.Quantity) AND NOT EXISTS(SELECT 1 FROM inventory.InventorySettings WHERE NegativeStockAllowed=1)THROW 51001,'Insufficient stock for transfer.',1;UPDATE b SET QuantityOnHand=QuantityOnHand-i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @i i ON b.ProductId=i.ProductId AND b.WarehouseId=@SourceWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.SourceBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');INSERT inventory.InventoryBalances(ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,QuantityOnHand,QuantityReserved,AverageCost,LastPurchaseCost,LastUpdated,CreatedOn,CreatedBy)SELECT ProductId,@DestinationWarehouseId,DestinationZoneId,DestinationBinId,BatchNo,SerialNo,0,0,UnitCost,UnitCost,SYSUTCDATETIME(),SYSUTCDATETIME(),@CreatedBy FROM @i i WHERE NOT EXISTS(SELECT 1 FROM inventory.InventoryBalances b WHERE b.ProductId=i.ProductId AND b.WarehouseId=@DestinationWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,''));UPDATE b SET QuantityOnHand=QuantityOnHand+i.Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy FROM inventory.InventoryBalances b JOIN @i i ON b.ProductId=i.ProductId AND b.WarehouseId=@DestinationWarehouseId AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationZoneId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(i.DestinationBinId,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'');
INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,SerialNo,Quantity,UnitCost)SELECT @out,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @i UNION ALL SELECT @in,ProductId,BatchNo,SerialNo,Quantity,UnitCost FROM @i;INSERT inventory.StockMovementHistory(TransactionId,TransactionDetailId,MovementDate,MovementType,ProductId,WarehouseId,ZoneId,BinId,BatchNo,SerialNo,Quantity,BalanceAfter,ReferenceType,ReferenceId,Remarks,CreatedBy)SELECT d.TransactionId,d.TransactionDetailId,@TransferDate,CASE WHEN d.TransactionId=@out THEN 'TRANSFER_OUT' ELSE 'TRANSFER_IN' END,d.ProductId,CASE WHEN d.TransactionId=@out THEN @SourceWarehouseId ELSE @DestinationWarehouseId END,CASE WHEN d.TransactionId=@out THEN i.SourceZoneId ELSE i.DestinationZoneId END,CASE WHEN d.TransactionId=@out THEN i.SourceBinId ELSE i.DestinationBinId END,d.BatchNo,d.SerialNo,CASE WHEN d.TransactionId=@out THEN -d.Quantity ELSE d.Quantity END,b.QuantityOnHand,'STOCK_TRANSFER',@id,@Remarks,@CreatedBy FROM inventory.InventoryTransactionDetails d JOIN @i i ON i.ProductId=d.ProductId AND ISNULL(i.BatchNo,'')=ISNULL(d.BatchNo,'') AND ISNULL(i.SerialNo,'')=ISNULL(d.SerialNo,'') LEFT JOIN inventory.InventoryBalances b ON b.ProductId=i.ProductId AND b.WarehouseId=CASE WHEN d.TransactionId=@out THEN @SourceWarehouseId ELSE @DestinationWarehouseId END AND ISNULL(b.ZoneId,'00000000-0000-0000-0000-000000000000')=ISNULL(CASE WHEN d.TransactionId=@out THEN i.SourceZoneId ELSE i.DestinationZoneId END,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BinId,'00000000-0000-0000-0000-000000000000')=ISNULL(CASE WHEN d.TransactionId=@out THEN i.SourceBinId ELSE i.DestinationBinId END,'00000000-0000-0000-0000-000000000000') AND ISNULL(b.BatchNo,'')=ISNULL(i.BatchNo,'') AND ISNULL(b.SerialNo,'')=ISNULL(i.SerialNo,'') WHERE d.TransactionId IN(@out,@in);END COMMIT;SELECT @id OperationId,@out TransactionId,@no Number;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE purchase.Purchase_AddPayment @PurchaseInvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF @Amount<=0 THROW 51200,'Payment must be positive.',1;BEGIN TRAN;DECLARE @Method UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2),@PaymentId UNIQUEIDENTIFIER=NEWID();SELECT @Grand=GrandTotal,@Paid=PaidAmount FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND IsDeleted=0 AND Status NOT IN('CANCELLED','DRAFT');IF @Method IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds outstanding balance.',1;END;INSERT purchase.PurchasePayments(PurchasePaymentId,PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PaymentId,@PurchaseInvoiceId,@Method,@Amount,@ReferenceNumber,@CreatedBy);UPDATE purchase.PurchaseInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;EXEC finance.PostPayment @Domain='PURCHASE',@PaymentId=@PaymentId,@CreatedBy=@CreatedBy;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE [purchase].[Purchase_Post] @SupplierId UNIQUEIDENTIFIER,@SupplierInvoiceNo NVARCHAR(100)=NULL,@InvoiceDate DATETIMEOFFSET,@DueDate DATETIMEOFFSET=NULL,@WarehouseId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@ExpensesJson NVARCHAR(MAX)=NULL,@PaymentsJson NVARCHAR(MAX)=NULL,@BillDiscount DECIMAL(18,2)=0,@RoundOff DECIMAL(18,2)=0,@Remarks NVARCHAR(1000)=NULL,@Status NVARCHAR(20)='POSTED',@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF @Status NOT IN('DRAFT','POSTED')THROW 51200,'Invalid purchase status.',1;IF NOT EXISTS(SELECT 1 FROM purchase.Suppliers WHERE SupplierId=@SupplierId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active supplier is required.',1;IF NOT EXISTS(SELECT 1 FROM inventory.Warehouses WHERE WarehouseId=@WarehouseId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active warehouse is required.',1;IF ISJSON(@ItemsJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@ItemsJson))THROW 51200,'Purchase requires items.',1;
DECLARE @Id UNIQUEIDENTIFIER=NEWID(),@SeriesId UNIQUEIDENTIFIER,@Prefix NVARCHAR(20),@Next BIGINT,@Len INT,@No NVARCHAR(50),@Subtotal DECIMAL(18,2),@ItemDiscount DECIMAL(18,2),@Tax DECIMAL(18,2),@Expenses DECIMAL(18,2)=0,@Grand DECIMAL(18,2),@Paid DECIMAL(18,2)=0,@Tx UNIQUEIDENTIFIER=NEWID();SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
SELECT TOP(1)@SeriesId=PurchaseSeriesId,@Prefix=Prefix,@Next=NextNumber,@Len=NumberLength FROM purchase.PurchaseSeries WITH(UPDLOCK,HOLDLOCK)WHERE IsDefault=1 AND IsActive=1;IF @SeriesId IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase series is not configured.',1;END;SET @No=CONCAT(@Prefix,'-',RIGHT(REPLICATE('0',@Len)+CONVERT(NVARCHAR(20),@Next),@Len));UPDATE purchase.PurchaseSeries SET NextNumber=NextNumber+1 WHERE PurchaseSeriesId=@SeriesId;
SELECT @Subtotal=SUM(Quantity*PurchasePrice),@ItemDiscount=SUM(CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END),@Tax=SUM((Quantity*PurchasePrice-CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END)*GSTPercentage/100)FROM OPENJSON(@ItemsJson)WITH(Quantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));IF ISJSON(@ExpensesJson)=1 SELECT @Expenses=ISNULL(SUM(Amount),0)FROM OPENJSON(@ExpensesJson)WITH(Amount DECIMAL(18,2));SET @Grand=ROUND(@Subtotal-@ItemDiscount-@BillDiscount+@Tax+@Expenses+@RoundOff,2);IF ISJSON(@PaymentsJson)=1 SELECT @Paid=ISNULL(SUM(Amount),0)FROM OPENJSON(@PaymentsJson)WITH(Amount DECIMAL(18,2));IF @Paid>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds purchase total.',1;END;
INSERT purchase.PurchaseInvoices(PurchaseInvoiceId,InvoiceNumber,SupplierId,SupplierInvoiceNo,InvoiceDate,DueDate,WarehouseId,Subtotal,DiscountAmount,TaxAmount,ExpenseAmount,RoundOff,GrandTotal,PaidAmount,Status,Remarks,CreatedBy,TenantId)VALUES(@Id,@No,@SupplierId,@SupplierInvoiceNo,@InvoiceDate,@DueDate,@WarehouseId,@Subtotal,@ItemDiscount+@BillDiscount,@Tax,@Expenses,@RoundOff,@Grand,@Paid,@Status,@Remarks,@CreatedBy,@TenantId);IF @Status='POSTED'INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy,TenantId)VALUES(@Tx,@No+'-STK',@InvoiceDate,'PURCHASE','PURCHASE_INVOICE',@Id,@WarehouseId,@Remarks,@CreatedBy,@TenantId);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Barcode NVARCHAR(100),BatchNo NVARCHAR(100),ExpiryDate DATE,Quantity DECIMAL(18,4),FreeQuantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),MRP DECIMAL(18,4),SellingPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));DECLARE @Product UNIQUEIDENTIFIER,@Barcode NVARCHAR(100),@Batch NVARCHAR(100),@Expiry DATE,@Qty DECIMAL(18,4),@Free DECIMAL(18,4),@Price DECIMAL(18,4),@MRP DECIMAL(18,4),@Sell DECIMAL(18,4),@DPct DECIMAL(5,2),@Disc DECIMAL(18,2),@GSTPct DECIMAL(5,2),@GST DECIMAL(18,2),@Line DECIMAL(18,2),@Allocated DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@OldQty DECIMAL(18,4),@OldCost DECIMAL(18,4),@StockQty DECIMAL(18,4),@NewCost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;WHILE @@FETCH_STATUS=0 BEGIN IF @Qty<=0 OR @Price<0 OR @MRP<@Sell OR NOT EXISTS(SELECT 1 FROM master.Products WHERE ProductId=@Product AND IsActive=1 AND IsDeleted=0)BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid purchase item.',1;END;SET @Disc=CASE WHEN ISNULL(@Disc,0)>0 THEN @Disc ELSE @Qty*@Price*ISNULL(@DPct,0)/100 END;SET @GST=(@Qty*@Price-@Disc)*ISNULL(@GSTPct,0)/100;SET @Line=ROUND(@Qty*@Price-@Disc+@GST,2);SET @Allocated=CASE WHEN @Subtotal>0 THEN @Expenses*(@Qty*@Price)/@Subtotal ELSE 0 END;INSERT purchase.PurchaseInvoiceItems(PurchaseInvoiceId,ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage,GSTAmount,AllocatedExpense,LineTotal)VALUES(@Id,@Product,@Barcode,NULLIF(@Batch,''),@Expiry,@Qty,ISNULL(@Free,0),@Price,@MRP,@Sell,ISNULL(@DPct,0),@Disc,ISNULL(@GSTPct,0),@GST,@Allocated,@Line);
IF @Status='POSTED'BEGIN SET @Balance=NULL;SET @OldQty=0;SET @OldCost=0;SET @StockQty=@Qty+ISNULL(@Free,0);SELECT @Balance=InventoryBalanceId,@OldQty=QuantityOnHand,@OldCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL BEGIN SET @Balance=NEWID();SET @OldQty=0;SET @OldCost=0;INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,BatchNo,QuantityOnHand,AverageCost,LastPurchaseCost,CreatedBy,TenantId)VALUES(@Balance,@Product,@WarehouseId,NULLIF(@Batch,''),0,0,@Price,@CreatedBy,@TenantId);END;SET @NewCost=CASE WHEN @OldQty+@StockQty=0 THEN @Price ELSE ((@OldQty*@OldCost)+(@Qty*@Price-@Disc+@Allocated))/(@OldQty+@StockQty) END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@StockQty,AverageCost=@NewCost,LastPurchaseCost=@Price,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,NULLIF(@Batch,''),@StockQty,@NewCost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost,ValuationDate)VALUES(@Product,@WarehouseId,'AVERAGE',@OldQty+@StockQty,@NewCost,@InvoiceDate);UPDATE master.Products SET PurchasePrice=@Price,MRP=@MRP,SellingPrice=@Sell,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE ProductId=@Product;END;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;END;CLOSE c;DEALLOCATE c;
IF ISJSON(@ExpensesJson)=1 INSERT purchase.PurchaseExpenses(PurchaseInvoiceId,ExpenseType,Description,Amount,IsTaxable)SELECT @Id,ExpenseType,Description,Amount,IsTaxable FROM OPENJSON(@ExpensesJson)WITH(ExpenseType NVARCHAR(50),Description NVARCHAR(250),Amount DECIMAL(18,2),IsTaxable BIT);IF ISJSON(@PaymentsJson)=1 INSERT purchase.PurchasePayments(PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)SELECT @Id,m.PaymentMethodId,j.Amount,j.ReferenceNumber,@CreatedBy FROM OPENJSON(@PaymentsJson)WITH(MethodCode NVARCHAR(30),Amount DECIMAL(18,2),ReferenceNumber NVARCHAR(100))j JOIN sales.PaymentMethods m ON m.MethodCode=j.MethodCode AND m.IsActive=1;EXEC finance.PostSource @SourceType='PURCHASE',@SourceId=@Id,@CreatedBy=@CreatedBy;COMMIT;SELECT @Id PurchaseInvoiceId,@No InvoiceNumber,@Grand GrandTotal,@Paid PaidAmount,@Grand-@Paid BalanceAmount,@Status Status;END;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE [purchase].[Purchase_Return] @PurchaseInvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51200,'Return items are required.',1;DECLARE @Warehouse UNIQUEIDENTIFIER,@Tx UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('PRET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),18))),@Adjustment DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @Warehouse=WarehouseId FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND Status IN('POSTED','PARTIALLY_RETURNED');IF @Warehouse IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@Tx,@ReturnNo+'-STK','RETURN','PURCHASE_RETURN',@PurchaseInvoiceId,@Warehouse,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT PurchaseItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(PurchaseItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @Item UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@Product UNIQUEIDENTIFIER,@Batch NVARCHAR(100),@Purchased DECIMAL(18,4),@Returned DECIMAL(18,4),@Free DECIMAL(18,4),@Line DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@Available DECIMAL(18,4),@Cost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Item,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @Product=ProductId,@Batch=BatchNo,@Purchased=Quantity,@Free=FreeQuantity,@Returned=ReturnedQuantity,@Line=LineTotal FROM purchase.PurchaseInvoiceItems WITH(UPDLOCK)WHERE PurchaseItemId=@Item AND PurchaseInvoiceId=@PurchaseInvoiceId;IF @Product IS NULL OR @Qty<=0 OR @Returned+@Qty>@Purchased+@Free BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid return quantity.',1;END;SELECT @Balance=InventoryBalanceId,@Available=QuantityAvailable,@Cost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@Warehouse AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL OR @Available<@Qty BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51201,'Insufficient stock for purchase return.',1;END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand-@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;UPDATE purchase.PurchaseInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE PurchaseItemId=@Item;DECLARE @Amount DECIMAL(18,2)=ROUND(@Line/NULLIF(@Purchased+@Free,0)*@Qty,2);SET @Adjustment+=@Amount;INSERT purchase.PurchaseReturns(ReturnNumber,PurchaseInvoiceId,PurchaseItemId,Quantity,AdjustmentAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@Item),4)),@PurchaseInvoiceId,@Item,@Qty,@Amount,@Reason,@CreatedBy);INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,@Batch,@Qty,@Cost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost)SELECT @Product,@Warehouse,'AVERAGE',QuantityOnHand,AverageCost FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance;FETCH NEXT FROM c INTO @Item,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE purchase.PurchaseInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM purchase.PurchaseInvoiceItems WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND ReturnedQuantity<Quantity+FreeQuantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;EXEC finance.PostSource @SourceType='PURCHASE_RETURN',@SourceId=@PurchaseInvoiceId,@CreatedBy=@CreatedBy;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@ReturnNo ReturnNumber,@Adjustment AdjustmentAmount,@Tx TransactionId;END;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE sales.POS_AddPayment @InvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF @Amount<=0 THROW 51100,'Payment amount must be positive.',1;BEGIN TRAN;DECLARE @MethodId UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2),@ShiftId UNIQUEIDENTIFIER,@PaymentId UNIQUEIDENTIFIER=NEWID();SELECT @Grand=GrandTotal,@Paid=PaidAmount,@ShiftId=ShiftId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status NOT IN('CANCELLED','VOID');IF @MethodId IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51100,'Payment exceeds balance.',1;END;INSERT sales.SalesPayments(PaymentId,InvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PaymentId,@InvoiceId,@MethodId,@Amount,@ReferenceNumber,@CreatedBy);UPDATE sales.SalesInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;IF @MethodCode='CASH'AND @ShiftId IS NOT NULL INSERT sales.CashDrawer(ShiftId,EntryType,Amount,ReferenceType,ReferenceId,CreatedBy)VALUES(@ShiftId,'SALE',@Amount,'SALES_INVOICE',@InvoiceId,@CreatedBy);EXEC finance.PostPayment @Domain='SALE',@PaymentId=@PaymentId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE [sales].[POS_ReturnInvoice] @InvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51100,'Return items are required.',1;DECLARE @WarehouseId UNIQUEIDENTIFIER,@ReturnTransactionId UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('RET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),20))),@Refund DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @WarehouseId=WarehouseId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status IN('COMPLETED','PARTIALLY_RETURNED');IF @WarehouseId IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@ReturnTransactionId,@ReturnNo+'-STK','RETURN','SALES_RETURN',@InvoiceId,@WarehouseId,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT InvoiceItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(InvoiceItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @ItemId UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@ProductId UNIQUEIDENTIFIER,@Sold DECIMAL(18,4),@Returned DECIMAL(18,4),@LineTotal DECIMAL(18,2),@UnitCost DECIMAL(18,4),@BalanceId UNIQUEIDENTIFIER;OPEN c;FETCH NEXT FROM c INTO @ItemId,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @ProductId=ProductId,@Sold=Quantity,@Returned=ReturnedQuantity,@LineTotal=LineTotal FROM sales.SalesInvoiceItems WITH(UPDLOCK)WHERE InvoiceItemId=@ItemId AND InvoiceId=@InvoiceId;IF @ProductId IS NULL OR @Qty<=0 OR @Returned+@Qty>@Sold BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51100,'Invalid return quantity.',1;END;SET @Refund=@Refund+(@LineTotal/@Sold*@Qty);UPDATE sales.SalesInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE InvoiceItemId=@ItemId;INSERT sales.SalesInvoiceReturns(ReturnNumber,InvoiceId,InvoiceItemId,Quantity,RefundAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@ItemId),4)),@InvoiceId,@ItemId,@Qty,@LineTotal/@Sold*@Qty,@Reason,@CreatedBy);SELECT @BalanceId=InventoryBalanceId,@UnitCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND BatchNo IS NULL AND SerialNo IS NULL;IF @BalanceId IS NULL BEGIN SET @BalanceId=NEWID();INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,CreatedBy)VALUES(@BalanceId,@ProductId,@WarehouseId,@CreatedBy);END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,Quantity,UnitCost)VALUES(@ReturnTransactionId,@ProductId,@Qty,ISNULL(@UnitCost,0));FETCH NEXT FROM c INTO @ItemId,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE sales.SalesInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM sales.SalesInvoiceItems WHERE InvoiceId=@InvoiceId AND ReturnedQuantity<Quantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;EXEC finance.PostSource @SourceType='SALE_RETURN',@SourceId=@InvoiceId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@ReturnNo ReturnNumber,@Refund RefundAmount,@ReturnTransactionId TransactionId;END;
GO

